import{_ as e,o as d,c as r,ai as a}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"API index","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),o={name:"reference/index.md"};function c(i,t,n,s,h,l){return d(),r("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/reference.md for this page in Markdown format</div><h1 id="api-index" tabindex="-1">API index <a class="header-anchor" href="#api-index" aria-label="Permalink to &quot;API index&quot;">​</a></h1><p>Every documented export, with the page that covers it. Use <kbd>Ctrl</kbd>/<kbd>⌘</kbd>+<kbd>F</kbd>.</p><p>For an explanation rather than a lookup, start from the <a href="/craft/guide/">Guide</a>. Coding agents: <a href="https://craft-ts.github.io/craft/llms.txt" target="_blank" rel="noreferrer">llms.txt</a> and <a href="/craft/resources/ai-agents.html">coding agents</a>.</p><h2 id="primitives" tabindex="-1">Primitives <a class="header-anchor" href="#primitives" aria-label="Permalink to &quot;Primitives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>state</code></td><td>Signal-based state you own</td><td><a href="/craft/guide/state/local-state.html">Local state</a></td></tr><tr><td><code>craftStateMachine</code></td><td>Declarative finite-state workflow</td><td><a href="/craft/guide/state/state-machines.html">State machines</a></td></tr><tr><td><code>query</code></td><td>Server data, re-fetched from reactive <code>params</code></td><td><a href="/craft/guide/state/server-state.html">query</a></td></tr><tr><td><code>mutation</code></td><td>Server write, triggered explicitly</td><td><a href="/craft/guide/state/mutations.html">Mutations</a></td></tr><tr><td><code>queryParams</code></td><td>State that lives in the URL query string</td><td><a href="/craft/guide/state/url-state.html">queryParams</a></td></tr><tr><td><code>asyncProcess</code></td><td>One-off async operation with lifecycle state</td><td><a href="/craft/guide/state/async-process.html">asyncProcess</a></td></tr><tr><td><code>craftUse</code></td><td>Drives a primitive outside a generator (component field)</td><td><a href="/craft/learn/01-first-state.html">Learn 1</a></td></tr></tbody></table><p>Not sure which one: <a href="/craft/guide/concepts/choose-primitive.html">Which primitive should I use?</a></p><h2 id="runtime-context" tabindex="-1">Runtime context <a class="header-anchor" href="#runtime-context" aria-label="Permalink to &quot;Runtime context&quot;">​</a></h2><p>Typed helpers that recover <code>get</code> / <code>set</code> / <code>update</code> / <code>patch</code> from DI, for wrappers, WebMCP tools, and other advanced patterns. Everyday insertions already receive those methods as arguments — see <a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy of a primitive</a>.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>injectStateMethodRuntimeContext</code></td><td><code>state</code> writes inside an insertion method</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>injectQueryMethodRuntimeContext</code></td><td><code>query</code> writes inside an insertion method</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>injectMutationMethodRuntimeContext</code></td><td><code>mutation</code> writes inside an insertion method</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>injectQueryParamsMethodRuntimeContext</code></td><td><code>queryParams</code> writes inside an insertion method</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>injectAsyncProcessMethodRuntimeContext</code></td><td><code>asyncProcess</code> writes inside an insertion method</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>injectPrimitiveMethodRuntimeContext</code></td><td>Same context, untyped <code>kind</code></td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr><tr><td><code>providePrimitiveResourceRuntimeObserver</code></td><td>Observes <code>query</code> / <code>mutation</code> / <code>asyncProcess</code> / <code>queryParams</code> values</td><td><a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">Anatomy</a></td></tr></tbody></table><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftPipe</code></td><td>Composes several insertions into one</td><td><a href="/craft/guide/concepts/insertions.html">Insertions</a></td></tr><tr><td><code>craftYieldRecord</code></td><td>Resolves a record of primitive generators</td><td><a href="/craft/guide/app/craft-service.html">craftService</a></td></tr><tr><td><code>insertStatePipe</code></td><td>Composes several <code>state</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>insertQueryPipe</code></td><td>Composes several <code>query</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>insertMutationPipe</code></td><td>Composes several <code>mutation</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>insertQueryParamsPipe</code></td><td>Composes several <code>queryParams</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>insertAsyncProcessPipe</code></td><td>Composes several <code>asyncProcess</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>insertStateMachinePipe</code></td><td>Composes several <code>craftStateMachine</code> insertions</td><td><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a></td></tr><tr><td><code>craftGen</code></td><td>A standalone tracked generator</td><td><a href="/craft/guide/concepts/generators.html">Generators</a></td></tr><tr><td><code>craftMatch</code></td><td>Exhaustive pattern matching</td><td><a href="/craft/guide/advanced/pattern-matching.html">Pattern matching</a></td></tr><tr><td><code>.pipe(...)</code></td><td>Program operators on a craft generator</td><td><a href="/craft/guide/advanced/program-operators.html">Program operators</a></td></tr><tr><td><code>catchTag</code>, <code>retry</code></td><td>Operators for <code>.pipe(...)</code></td><td><a href="/craft/guide/advanced/program-operators.html">Program operators</a></td></tr></tbody></table><h2 id="insertions" tabindex="-1">Insertions <a class="header-anchor" href="#insertions" aria-label="Permalink to &quot;Insertions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>insertSelect</code></td><td>Derives a slice of a primitive</td><td><a href="/craft/guide/state/select.html">Selecting</a></td></tr><tr><td><code>insertEntities</code></td><td>Entity collection storage and updates</td><td><a href="/craft/guide/state/collections.html">Collections</a></td></tr><tr><td><code>insertStoragePersister</code></td><td>Persists through the configured storage backend</td><td><a href="/craft/guide/state/persistence.html">Persistence</a></td></tr><tr><td><code>insertReactOnMutation</code></td><td>Reloads / optimistically patches on a mutation</td><td><a href="/craft/guide/state/react-on-mutation.html">React on mutation</a></td></tr><tr><td><code>insertPaginationPlaceholderData</code></td><td>Placeholder rows while a page loads</td><td><a href="/craft/guide/state/pagination-placeholder.html">Pagination placeholder</a></td></tr></tbody></table><h2 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>insertForm</code></td><td>Derives a form from a <code>state</code></td><td><a href="/craft/guide/forms/">Forms</a></td></tr><tr><td><code>insertFormAttributes</code></td><td>Validators, <code>disable</code>, <code>hidden</code></td><td><a href="/craft/guide/forms/">Forms</a></td></tr><tr><td><code>insertSelectFormTree</code></td><td>Targets a field sub-tree</td><td><a href="/craft/guide/forms/nested.html">Nested forms</a></td></tr><tr><td><code>insertSubFormField</code></td><td>A nested sub-form</td><td><a href="/craft/guide/forms/nested.html">Nested forms</a></td></tr><tr><td><code>insertFormSubmit</code></td><td>Wires submission to a mutation</td><td><a href="/craft/guide/forms/submit.html">Submitting</a></td></tr><tr><td><code>insertNoopTypingAnchor</code></td><td>Type anchor required per field tree</td><td><a href="/craft/guide/forms/">Forms</a></td></tr><tr><td><code>CraftFieldDirective</code></td><td>Binds a typed field to a Craft DOM node</td><td><a href="/craft/guide/forms/">Forms</a></td></tr><tr><td><code>fieldErrorNode.exhaustive</code> / <code>.partial</code></td><td>Exhaustive or partial validation rendering</td><td><a href="/craft/guide/forms/">Forms</a></td></tr><tr><td><code>cRequired</code>, <code>cEmail</code>, <code>cMin</code>/<code>cMax</code>, <code>cMinLength</code>/<code>cMaxLength</code>, <code>cPattern</code></td><td>Built-in validators</td><td><a href="/craft/guide/forms/validation.html">Validators</a></td></tr><tr><td><code>cValidate</code>, <code>cAsyncValidate</code></td><td>Custom and async validators</td><td><a href="/craft/guide/forms/validation.html">Validators</a></td></tr></tbody></table><h2 id="services-and-di" tabindex="-1">Services and DI <a class="header-anchor" href="#services-and-di" aria-label="Permalink to &quot;Services and DI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftService</code></td><td>Declares a named, scoped service</td><td><a href="/craft/guide/app/craft-service.html">craftService</a></td></tr><tr><td><code>abstract</code></td><td>Declares a contract with no implementation</td><td><a href="/craft/guide/app/abstract-services.html">Abstract services</a></td></tr><tr><td><code>X.OmitInputs</code></td><td>Opts out of a service&#39;s input bindings</td><td><a href="/craft/guide/app/expose-api.html">Public API</a></td></tr><tr><td><code>onAppStart</code></td><td>Startup callback owned by a service</td><td><a href="/craft/guide/app/app-start.html">App start</a></td></tr><tr><td><code>craftLazy</code></td><td>Defers a service&#39;s instantiation</td><td><a href="/craft/guide/app/lazy-services.html">Lazy services</a></td></tr><tr><td><code>craftRegisterFor</code></td><td>Registry-driven service resolution</td><td><a href="/craft/guide/app/register.html">Register</a></td></tr><tr><td><code>provideCraftTargetWrapper</code></td><td>Wraps craft targets at a provider boundary</td><td><a href="/craft/guide/app/target-wrapper.html">Target wrapper</a></td></tr><tr><td><code>provideTemplateTrace</code></td><td>Wraps effective template renders</td><td><a href="/craft/guide/advanced/observability.html">Observability</a></td></tr><tr><td><code>provideCraftRouterTrace</code></td><td>Wraps Router events and Craft route stages</td><td><a href="/craft/guide/advanced/observability.html">Observability</a></td></tr><tr><td><code>provideCraftHttpTrace</code></td><td>Wraps CraftHttpClient requests</td><td><a href="/craft/guide/advanced/observability.html">Observability</a></td></tr><tr><td><code>craftAppConfig</code></td><td>Application config with the routing graph</td><td><a href="/craft/guide/routing/setup.html">Routing setup</a></td></tr></tbody></table><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftRoute</code>, <code>craftRoutes</code></td><td>Declares typed routes and collections</td><td><a href="/craft/guide/routing/setup.html">Setup</a></td></tr><tr><td><code>ValidateCascadeRoutesFile</code>, <code>CanRun</code></td><td>Compile-time DI check for a routes file</td><td><a href="/craft/guide/routing/setup.html">Setup</a></td></tr><tr><td><code>RouteCheckedDI</code></td><td>Per-route <code>O(1)</code> variant of the check</td><td><a href="/craft/guide/routing/scaling.html">Scaling routes</a></td></tr><tr><td><code>.withParent</code>, <code>ParentRoutes</code>, <code>assertChildRouteMounts</code></td><td>Pins a child collection to its mount</td><td><a href="/craft/guide/routing/scaling.html">Scaling routes</a></td></tr><tr><td><code>withRetry</code></td><td>Retryable lazy <code>loadComponent</code> / <code>loadChildren</code></td><td><a href="/craft/guide/routing/setup.html">Setup</a></td></tr><tr><td><code>provideCraftRouter</code>, <code>provideCraftLoading</code></td><td>Router with craft loading features</td><td><a href="/craft/guide/routing/pending-ui.html">Pending UI</a></td></tr><tr><td><code>withA11yNavigationFocus</code>, <code>CraftTitleStrategy</code></td><td>Focus after nav; route <code>title</code> → document</td><td><a href="/craft/guide/components/accessibility.html">Accessibility</a></td></tr><tr><td><code>heading</code>, <code>headingSection</code>, <code>headingRoot</code>, <code>skipLink</code>, <code>liveRegion</code>, <code>fieldControl</code>, <code>disclosureControl</code>, <code>buttonControl</code>, <code>clickFocus</code></td><td>Relative outline, skip link, live regions, accessible control props, focus</td><td><a href="/craft/guide/components/accessibility.html">Accessibility</a></td></tr><tr><td><code>withErrorComponent</code>, <code>withRouteLoadError</code>, <code>withTransitionTimings</code></td><td>Router features</td><td><a href="/craft/guide/routing/route-load-errors.html">Route load errors</a></td></tr><tr><td><code>CraftRouterOutlet</code></td><td>Non-blocking outlet</td><td><a href="/craft/guide/routing/pending-ui.html">Pending UI</a></td></tr><tr><td><code>craftRouterLink</code></td><td>Type-safe navigation target</td><td><a href="/craft/guide/routing/setup.html">Setup</a></td></tr><tr><td><code>assertExhaustiveRouteExceptions</code></td><td>Exhaustiveness proof for route exceptions</td><td><a href="/craft/guide/concepts/exceptions.html">Exceptions</a></td></tr></tbody></table><h2 id="server-rendering" tabindex="-1">Server rendering <a class="header-anchor" href="#server-rendering" aria-label="Permalink to &quot;Server rendering&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>renderCraft</code>, <code>renderToString</code></td><td>Renders an isolated request to HTML, CSS, and a transfer snapshot</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr><tr><td><code>startCraft</code></td><td>Hydrates an SSR host or mounts a fresh client application automatically</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr><tr><td><code>hydrateCraft</code></td><td>Restores transferred state and claims the existing browser DOM</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr><tr><td><code>pendingNode({ ssr })</code></td><td>Declares <code>block</code>, <code>fallback</code>, or <code>client</code> behavior for suspended data</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr><tr><td><code>CRAFT_SSR_POLICY</code></td><td>Route-level default SSR policy</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr><tr><td><code>CraftUnhandledSsrResolutionError</code>, <code>CraftSsrTimeoutError</code></td><td>Reports missing policies and timed-out blocking sources</td><td><a href="/craft/guide/advanced/ssr-hydration.html">SSR and hydration</a></td></tr></tbody></table><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftException</code></td><td>Creates a declared, typed exception</td><td><a href="/craft/guide/concepts/exceptions.html">Exceptions</a></td></tr><tr><td><code>craftExceptionHandler</code></td><td>Handles route exceptions</td><td><a href="/craft/guide/concepts/exceptions.html">Exceptions</a></td></tr><tr><td><code>.exceptions()</code>, <code>.hasException()</code></td><td>Reads a primitive&#39;s exceptions by origin</td><td><a href="/craft/guide/state/server-state.html">query</a></td></tr><tr><td><code>globalError()</code></td><td>Delegates to the global error component</td><td><a href="/craft/guide/routing/global-error-component.html">Global error component</a></td></tr></tbody></table><h2 id="reactivity" tabindex="-1">Reactivity <a class="header-anchor" href="#reactivity" aria-label="Permalink to &quot;Reactivity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftComputed</code></td><td>Tracked <code>computed</code></td><td><a href="/craft/guide/reactivity/craft-computed.html">craftComputed</a></td></tr><tr><td><code>craftEffect</code></td><td>Tracked <code>effect</code></td><td><a href="/craft/guide/reactivity/craft-effect.html">craftEffect</a></td></tr><tr><td><code>craftMethod</code></td><td>A tracked method on a primitive</td><td><a href="/craft/guide/reactivity/craft-method.html">craftMethod</a></td></tr><tr><td><code>source$</code></td><td>An imperative event source</td><td><a href="/craft/guide/reactivity/source.html">source$</a></td></tr><tr><td><code>on$</code></td><td>Binds a method to a source</td><td><a href="/craft/guide/reactivity/on.html">on$</a></td></tr><tr><td><code>fromEventToSource$</code></td><td>DOM event → source</td><td><a href="/craft/guide/reactivity/from-event-to-source.html">fromEventToSource$</a></td></tr><tr><td><code>sourceFromEvent</code></td><td>Event-driven source helper</td><td><a href="/craft/guide/reactivity/source-from-event.html">sourceFromEvent</a></td></tr><tr><td><code>afterRecomputation</code></td><td>Runs after a recomputation settles</td><td><a href="/craft/guide/reactivity/after-recomputation.html">afterRecomputation</a></td></tr></tbody></table><h2 id="http-and-boundaries" tabindex="-1">HTTP and boundaries <a class="header-anchor" href="#http-and-boundaries" aria-label="Permalink to &quot;HTTP and boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>CraftHttpClient</code></td><td>Tracked HTTP client with typed exceptions</td><td><a href="/craft/guide/state/server-state.html">query</a></td></tr><tr><td><code>browserBoundary</code></td><td>Marks a service as a browser boundary</td><td><a href="/craft/guide/testing/browser-boundaries.html">Browser boundaries</a></td></tr><tr><td><code>BrowserDocument</code>, <code>BrowserDocument.setLang</code>, <code>BrowserDocument.setDir</code></td><td>Reads and updates document title, language, and direction</td><td><a href="/craft/guide/testing/browser-boundaries.html">Browser boundaries</a></td></tr><tr><td><code>Console</code></td><td>Yieldable console, overridable for tracing</td><td><a href="/craft/guide/advanced/observability.html">Observability</a></td></tr></tbody></table><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>setupCraftServiceTestingByRegister</code></td><td>Sets up a service from a full register</td><td><a href="/craft/guide/testing/services.html">Testing services</a></td></tr><tr><td><code>boundaryOnly</code></td><td>Keeps the graph real, mocks boundaries</td><td><a href="/craft/guide/testing/browser-boundaries.html">Browser boundaries</a></td></tr><tr><td><code>mockHttpRequestForRoute</code></td><td>Mocks endpoints for a route</td><td><a href="/craft/guide/testing/browser-boundaries.html">Browser boundaries</a></td></tr><tr><td><code>ComponentTemplateOf</code>, <code>ComponentLogicOutputOf</code>, <code>SetupTestComponentTemplate</code></td><td>Resolves component logic and validates a template at compile time</td><td><a href="/craft/guide/testing/type-level.html">Type-level tests</a></td></tr><tr><td><code>TemplateHasElement</code>, <code>TemplateRendersNamedElementWhen</code>, <code>TemplateNamedElementRendersStateWhen</code>, <code>TemplateNamedElementDelegatesToContext</code>, <code>TemplateRenderAvailableActionWhen</code></td><td>Proves what a template renders and uses</td><td><a href="/craft/guide/testing/type-level.html">Type-level tests</a></td></tr><tr><td><code>Expect</code>, <code>Equal</code></td><td>Turns a type-level result into a compile-time assertion</td><td><a href="/craft/guide/testing/type-level.html">Type-level tests</a></td></tr><tr><td><code>createArchitectureGraph</code>, <code>noExclusiveLink</code>, <code>assertCraftUnique</code>, <code>assertHttpEndpointUnique</code>, <code>assertCraftComputedPure</code>, <code>assertNoDependencyCycles</code>, <code>assertDeclarativeArchitecture</code>, <code>assertRouteDiProofs</code>, <code>assertPathBoundaries</code>, <code>assertMutationHasReactOn</code>, <code>assertPrimitiveLoaderRequirements</code>, <code>assertQueryMutationHasServerState</code>, <code>assertResourceParamsPreferQueryParams</code>, <code>assertPersistedPrimitiveHasUnique</code>, <code>assertInsertSelectUnique</code>, <code>assertCraftEffectNoNetwork</code>, <code>assertCraftEffectNoImperativeSync</code>, <code>assertInteractiveElementNamed</code></td><td>Typed lookups and declarative architecture helpers</td><td><a href="/craft/guide/testing/architecture.html">Architecture rules</a></td></tr></tbody></table><h2 id="effect-integration" tabindex="-1">Effect integration <a class="header-anchor" href="#effect-integration" aria-label="Permalink to &quot;Effect integration&quot;">​</a></h2><p><code>@craft-ts/effect</code>, in full. The guide is <a href="/craft/guide/advanced/effect.html">Effect integration</a>.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>installCraftEffectBridge</code></td><td>Installs both bridges once, at bootstrap</td><td><a href="/craft/guide/advanced/effect.html#install-the-bridge-once">Install the bridge</a></td></tr><tr><td><code>queryEffect</code>, <code>mutationEffect</code>, <code>asyncProcessEffect</code>, <code>computedEffect</code>, <code>methodEffect</code></td><td>The Effect-backed adapters of the Craft primitives</td><td><a href="/craft/guide/advanced/effect.html#choose-the-right-adapter">Choose the right adapter</a></td></tr><tr><td><code>runEffect</code>, <code>CraftEffectInterrupted</code></td><td>Yields one Effect and maps its exit onto Craft&#39;s channels</td><td><a href="/craft/guide/advanced/effect.html#runeffect-the-low-level-form">runEffect</a></td></tr><tr><td><code>syncEffect</code>, <code>SyncOp</code>, <code>CraftEffectNotSynchronous</code>, <code>NotDeclaredSynchronous</code></td><td>Declares and runs an Effect that never suspends</td><td><a href="/craft/guide/advanced/effect.html#run-a-synchronous-member-from-a-computed">Synchronous members</a></td></tr><tr><td><code>provideLayer</code></td><td>Attaches a built Effect context to a Craft injector</td><td><a href="/craft/guide/advanced/effect.html#provide-services-with-layer">Provide services with Layer</a></td></tr><tr><td><code>effectService</code>, <code>SelectedMembers</code></td><td>Selects a service from a Craft factory, recording the dependency</td><td><a href="/craft/guide/advanced/effect.html#select-an-effect-service-from-craft">Select a service</a></td></tr><tr><td><code>mockEffectService</code>, <code>UnstubbedEffectMember</code></td><td>A focused Layer for tests; an unstubbed member fails loudly</td><td><a href="/craft/guide/advanced/effect.html#testing">Testing</a></td></tr><tr><td><code>EffectRequirementsCheckedDI</code>, <code>ProvidedEffectServicesOf</code>, <code>ProvidedEffectServicesOfRoute</code></td><td>The route-level proof that every requirement is provided</td><td><a href="/craft/guide/advanced/effect.html#provide-services-with-layer">Provide services with Layer</a></td></tr><tr><td><code>effectServerMiddleware</code>, <code>executeEffect</code>, <code>EffectServerMiddleware</code>, <code>EffectServerMiddlewareContext</code></td><td>Effect middleware and execution for server functions</td><td><a href="/craft/guide/advanced/effect.html#server-functions-current-poc">Server functions POC</a></td></tr></tbody></table><h3 id="lower-level-exports" tabindex="-1">Lower-level exports <a class="header-anchor" href="#lower-level-exports" aria-label="Permalink to &quot;Lower-level exports&quot;">​</a></h3><p>Public, but rarely needed directly. They exist for wrappers, generated code and tooling rather than for application code.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it is</th></tr></thead><tbody><tr><td><code>composeEffect</code></td><td>Composes yieldable Effect middleware in declaration order, without continuations. <code>effectServerMiddleware</code> is the everyday door.</td></tr><tr><td><code>runYieldedEffect</code></td><td>The single-Effect runner the bridge itself calls. Use <code>runEffect</code>, which keeps the call site blamable.</td></tr><tr><td><code>assertNoRequirements</code>, <code>AssertNoRequirements</code>, <code>MissingRequirements</code>, <code>RealRequirements</code>, <code>CraftPhantomRequirement</code></td><td>Moves the <code>R = never</code> check to the <strong>yield site</strong>, so an unmet requirement points at the offending line instead of surfacing at runtime. <code>CraftPhantomRequirement</code> is what excludes <code>SyncOp</code> from that check.</td></tr><tr><td><code>CRAFT_EFFECT_LEVEL</code>, <code>resolveEffectLevel</code>, <code>CraftEffectLevel</code></td><td>The per-injector Effect level: the built context, a <code>MemoMap</code> forked from the parent&#39;s, and a scope closed with the injector. Read it when writing your own provider; <code>provideLayer</code> is the normal way in.</td></tr><tr><td><code>AsEffect</code>, <code>CraftProgramSuccess</code>, <code>CraftProgramExceptions</code></td><td>A <strong>type-only projection</strong> of a Craft program onto <code>Effect&lt;A, E&gt;</code>. It changes no runtime behaviour; it exists so a hover tooltip reads <code>Effect&lt;User, UserNotFound&gt;</code> instead of a raw generator type.</td></tr><tr><td><code>installCraftSyncEffectBridge</code></td><td>Already installed by <code>installCraftEffectBridge</code>. Call it directly only in a host that installs the synchronous bridge alone.</td></tr></tbody></table><h2 id="typed-styles" tabindex="-1">Typed styles <a class="header-anchor" href="#typed-styles" aria-label="Permalink to &quot;Typed styles&quot;">​</a></h2><p><code>@craft-ts/style</code> is a <strong>build step</strong>: none of these symbols emit anything without <code>craftStyle</code> from <code>@craft-ts/style/vite</code> in the Vite config. See <a href="/craft/guide/style/setup.html">Activating the style system</a>.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>craftStyle</code>, <code>emitStyles</code>, <code>renderCss</code>, <code>styleDump</code>, <code>findStyleModules</code></td><td>The build-time emitter and its artefacts (<code>@craft-ts/style/vite</code>)</td><td><a href="/craft/guide/style/setup.html">Activating the style system</a></td></tr><tr><td><code>definePalette</code>, <code>darkOf</code>, <code>palette</code></td><td>Colour tokens carrying both of their values, plus the default set</td><td><a href="/craft/guide/style/define.html">Defining a design system</a></td></tr><tr><td><code>defineBreakpoints</code>, <code>at</code>, <code>above</code>, <code>below</code></td><td>The viewport axis, as an ordered one</td><td><a href="/craft/guide/style/define.html">Defining a design system</a></td></tr><tr><td><code>defineStateAxis</code>, <code>defineAxis</code>, <code>onlyVarsOfKind</code>, <code>axisPoint</code></td><td>Attribute-driven axes, with an optional write constraint</td><td><a href="/craft/guide/style/define.html">Defining a design system</a></td></tr><tr><td><code>defineContainer</code></td><td>A container axis, closed at the element that declares the container</td><td><a href="/craft/guide/style/define.html">Defining a design system</a></td></tr><tr><td><code>scheme</code>, <code>motion</code>, <code>forcedColors</code>, <code>contrast</code>, <code>scrollState</code>, <code>descendant</code></td><td>The standard axes, driven by the user agent or by element state</td><td><a href="/craft/guide/style/variants.html">Axes and the matrix</a></td></tr><tr><td><code>cssVars</code>, <code>kind</code>, <code>assign</code>, <code>set</code></td><td>Typed custom properties, registered through <code>@property</code></td><td><a href="/craft/guide/style/tokens.html">Tokens and variables</a></td></tr><tr><td><code>space</code>, <code>unit</code>, <code>radii</code>, <code>radius</code>, <code>lineWidth</code>, <code>num</code>, <code>text</code>, <code>font</code></td><td>The closed value scales — no value is a string</td><td><a href="/craft/guide/style/tokens.html">Tokens and variables</a></td></tr><tr><td><code>unsafeLength</code>, <code>unsafeAssume</code></td><td>The marked escape hatches; both propagate <code>unproven</code></td><td><a href="/craft/guide/style/tokens.html">Tokens and variables</a></td></tr><tr><td><code>craftStyles</code>, <code>when</code></td><td>A sheet, and conjunction by nesting</td><td><a href="/craft/guide/style/variants.html">Axes and the matrix</a></td></tr><tr><td><code>requires</code>, <code>provides</code>, <code>declares</code>, <code>seal</code>, <code>scrollPort</code>, <code>noClipping</code>, <code>containerType</code>, <code>clipOverflow</code></td><td>Context obligations, and where they become an error</td><td><a href="/craft/guide/style/obligations.html">Context obligations</a></td></tr><tr><td><code>visualMatrix</code>, <code>applyScenario</code>, <code>branch</code>, <code>contentCases</code>, <code>assertExhaustiveVisualMatrix</code>, <code>baselinesIn</code></td><td>The scenario matrix (<code>@craft-ts/style-testing</code>)</td><td><a href="/craft/guide/style/testing.html">Testing visual states</a></td></tr><tr><td><code>matrixSizeByComponent</code>, <code>impactedClasses</code>, <code>varsWrittenBy</code>, <code>danglingVars</code>, <code>unproven</code>, <code>extractionGaps</code>, <code>undischargedObligations</code></td><td>Graph queries over the style dump (<code>@craft-ts/dev-tools</code>)</td><td><a href="/craft/guide/style/testing.html">Testing visual states</a></td></tr><tr><td><code>style_impact</code>, <code>style_matrix</code>, <code>style_debt</code></td><td>The same questions as MCP tools</td><td><a href="/craft/guide/style/testing.html#the-same-questions-from-an-agent">Testing visual states</a></td></tr></tbody></table><h2 id="internationalisation" tabindex="-1">Internationalisation <a class="header-anchor" href="#internationalisation" aria-label="Permalink to &quot;Internationalisation&quot;">​</a></h2><p><code>@craft-ts/i18n</code> is the CraftTS i18n integration: the catalogue stays a plain TypeScript value, and a token may resolve a Craft service or parse its parameter with a Standard Schema. The package imports core for types only.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>defineCatalog</code>, <code>msg</code>, <code>plural</code></td><td>The catalogue, its messages, and per-locale plural categories</td><td><a href="/craft/guide/i18n/catalog.html">The catalogue</a></td></tr><tr><td><code>defineLocale</code>, <code>defineLocaleLike</code></td><td>The reference locale, and every other one checked against it</td><td><a href="/craft/guide/i18n/catalog.html">The catalogue</a></td></tr><tr><td><code>number</code>, <code>integer</code>, <code>percent</code>, <code>compactNumber</code>, <code>money</code>, <code>dateShort</code>, <code>dateLong</code>, <code>dateTime</code>, <code>relativeTime</code></td><td>The shipped semantic tokens, formatted through <code>Intl</code></td><td><a href="/craft/guide/i18n/tokens.html">Tokens</a></td></tr><tr><td><code>defineToken</code>, <code>defineTokenFactory</code>, <code>formatters</code>, <code>TokenFormatter</code>, <code>FormatterContext</code></td><td>Project tokens, and the factory the shipped ones are built from</td><td><a href="/craft/guide/i18n/tokens.html">Tokens</a></td></tr><tr><td><code>createI18nRuntime</code>, <code>translate</code> / <code>t</code>, <code>setLocale</code>, <code>locale</code></td><td>The runtime and its one active locale</td><td><a href="/craft/guide/i18n/runtime.html">The runtime</a></td></tr><tr><td><code>TranslationDependencies</code>, <code>StaticTranslationKey</code></td><td>The services a message resolves, and the keys <code>t</code> can render alone</td><td><a href="/craft/guide/i18n/runtime.html#di-inside-a-translation">The runtime</a></td></tr><tr><td><code>TokenSchema</code>, <code>TokenSchemaInput</code>, <code>TokenSchemaOutput</code>, <code>TokenFactory</code></td><td>Declaring a parameter with a Standard Schema</td><td><a href="/craft/guide/i18n/tokens.html">Tokens</a></td></tr><tr><td><code>bind</code>, <code>createReactiveTranslator</code></td><td>A translator that re-reads when the locale state changes</td><td><a href="/craft/guide/i18n/runtime.html#reactive-translation">The runtime</a></td></tr><tr><td><code>createI18nLoader</code>, <code>loadLocale</code></td><td>Lazy locales, cached by id, evicted on failure</td><td><a href="/craft/guide/i18n/runtime.html#lazy-locales">The runtime</a></td></tr><tr><td><code>validateCatalog</code>, <code>assertValidCatalog</code>, <code>validateLocaleParity</code>, <code>assertLocaleParity</code></td><td>The checks behind <code>npm run i18n:check</code> (also <code>@craft-ts/i18n/testing</code>)</td><td><a href="/craft/guide/i18n/catalog.html#checking-outside-the-typechecker">The catalogue</a></td></tr><tr><td><code>serializeCatalog</code>, <code>serializeToken</code></td><td>JSON-safe delivery shape; refuses a token that resolves a service</td><td><a href="/craft/guide/i18n/catalog.html">The catalogue</a></td></tr><tr><td><code>I18nRuntimeError</code></td><td><code>LOCALE_NOT_LOADED</code>, <code>MISSING_PARAM</code>, <code>INVALID_PARAM</code>, <code>CRAFT_INJECTION_REQUIRED</code>, …</td><td><a href="/craft/guide/i18n/runtime.html">The runtime</a></td></tr><tr><td><code>provideI18nRuntime</code>, <code>translateEffect</code>, <code>I18nEffectService</code></td><td>The Effect adapter (<code>@craft-ts/i18n-effect</code>)</td><td><a href="/craft/guide/i18n/effect.html">With Effect</a></td></tr></tbody></table><h2 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command / rule</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>npx craft route add</code></td><td>Scaffolds a typed route</td><td><a href="/craft/guide/routing/automation.html">Automation</a></td></tr><tr><td><code>npx craft route split</code></td><td>Splits a flat collection</td><td><a href="/craft/guide/routing/scaling.html">Scaling routes</a></td></tr><tr><td><code>npx craft route verify</code></td><td>Optional compiler-fixture suite for the type machinery</td><td><a href="/craft/guide/routing/automation.html#compiler-fixture-suite-optional">Automation</a></td></tr><tr><td><code>craft-brand --root src</code></td><td>Generates and refreshes <code>GenDeps_*</code></td><td><a href="/craft/guide/routing/setup.html#generated-dependencies">Brand config</a></td></tr><tr><td><code>@craft-ts/dev-tools/eslint-rules</code></td><td>The ESLint rule set</td><td><a href="/craft/guide/routing/eslint-rules.html">ESLint rules</a> · <a href="/craft/guide/components/accessibility.html">Accessibility</a></td></tr><tr><td><code>npx craft-graph</code></td><td>Writes the static Craft graph</td><td><a href="/craft/guide/testing/architecture.html">Architecture rules</a> · <a href="/craft/guide/testing/craft-graph-vs-nx.html">Craft graph vs Nx</a></td></tr><tr><td><code>npx nx architecture &lt;app&gt;</code></td><td>Runs the app&#39;s architecture Vitest suite</td><td><a href="/craft/guide/testing/architecture.html">Architecture rules</a> · <a href="/craft/guide/testing/craft-graph-vs-nx.html">Craft graph vs Nx</a></td></tr><tr><td>Live page MCP <code>page</code></td><td>Drive the open <code>ng serve</code> tab (dev only)</td><td><a href="/craft/guide/ai/dev-page.html">Live page MCP</a></td></tr><tr><td>Template migrator</td><td>Migrates templates to craft components</td><td><a href="/craft/guide/components/template-migrator.html">Template migrator</a></td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Experimental</p><p>The deployment tooling is not settled: these symbols and commands can still change between minor versions. See the <a href="/craft/guide/deployment/">deployment guide</a> for what exists today.</p></div><table tabindex="0"><thead><tr><th>Symbol / command</th><th>What it does</th><th>Page</th></tr></thead><tbody><tr><td><code>defineCraftDeployment</code></td><td>Declares the deployment of an application in <code>craft.deploy.ts</code></td><td><a href="/craft/guide/deployment/manifest.html">Manifest reference</a></td></tr><tr><td><code>checkCraftDeployment</code>, <code>checkCraftDeploymentArtifact</code></td><td>Runs the manifest, module graph and artefact checks</td><td><a href="/craft/guide/deployment/diagnostics.html">Diagnostics</a></td></tr><tr><td><code>resolveCraftDeploymentManifest</code>, <code>serializeCraftDeploymentManifest</code>, <code>parseCraftDeploymentManifest</code></td><td>Resolves, writes and reads the provider-neutral artefact form</td><td><a href="/craft/guide/deployment/manifest.html">Manifest reference</a></td></tr><tr><td><code>CraftDeploymentProvider</code>, <code>CRAFT_DEPLOYMENT_PROVIDERS</code></td><td>The provider contract and the capability matrix</td><td><a href="/craft/guide/deployment/providers.html">Providers</a></td></tr><tr><td><code>npx craft-ts check</code></td><td>Validates a deployment before building</td><td><a href="/craft/guide/deployment/">Deployment overview</a></td></tr><tr><td><code>npx craft-ts manifest</code></td><td>Writes <code>dist/&lt;app&gt;/craft-deployment-manifest.json</code></td><td><a href="/craft/guide/deployment/">Deployment overview</a></td></tr><tr><td><code>npx craft-ts deploy preview</code></td><td>Shows what a provider would change, without changing it</td><td><a href="/craft/guide/deployment/alchemy.html">Alchemy provider</a></td></tr><tr><td><code>npx craft-ts deploy</code></td><td>Applies that plan once <code>--yes</code> approves it</td><td><a href="/craft/guide/deployment/alchemy.html">Alchemy provider</a></td></tr><tr><td><code>createCraftDeploymentProvider</code></td><td>The single factory a provider package exports</td><td><a href="/craft/guide/deployment/providers.html">Providers</a></td></tr><tr><td><code>createAlchemyDeploymentProvider</code>, <code>planAlchemyDeployment</code></td><td>The Alchemy provider and its Cloudflare/AWS planning</td><td><a href="/craft/guide/deployment/alchemy.html">Alchemy provider</a></td></tr><tr><td><code>npx craft-ts providers</code></td><td>Prints the provider capability matrix</td><td><a href="/craft/guide/deployment/providers.html">Providers</a></td></tr></tbody></table>',47)])])}const m=e(o,[["render",c]]);export{u as __pageData,m as default};
